static long parseHour(String field, String value) {
    long nanos = parseInstant(field, value);
    if (nanos % HOUR_NANOS != 0) throw badRequest("CURVE_HOUR_NOT_ALIGNED", field + " 必须整点对齐...");
    return nanos;
}
