public BatchApproveResponse approveBatch(String commandKey, List<String> allocationKeys) {
    requireKey("commandKey", commandKey);
    if (allocationKeys == null || allocationKeys.isEmpty()) throw 400;
    Set<String> seen = new HashSet<>(); for key: requireKey; if (!seen.add) throw 400 BATCH_DUPLICATE_KEY;
    String params = "ALLOCATION_APPROVE_BATCH|" + String.join(",", allocationKeys);
    return runCommand("ALLOCATION_APPROVE_BATCH", commandKey, params, BatchApproveResponse.class, () -> {
        // 查找全部申请
        Map<String, AllocationRow> byKey = new LinkedHashMap<>();
        for (String key : allocationKeys) {
            AllocationRow row = repository.findAllocationByKey(key);
            if (row == null) throw notFound("ALLOCATION_NOT_FOUND", ...);
            byKey.put(key, row);
        }
        // 按窗口分组并升序锁定窗口行
        List<Long> windowIds = distinct sorted;
        Map<Long, WindowRow> windows = new HashMap<>();
        for (Long id : windowIds) {
            WindowRow w = repository.lockWindowById(id);
            if (w == null) throw notFound WINDOW_NOT_FOUND;
            windows.put(id, w);
        }
        // 锁内重读申请并校验状态
        List<AllocationRow> locked = new ArrayList<>();
        for (String key : allocationKeys) {
