        // 非整点 -> 400
        putCurve(windowId, 400, "2026-10-21T00:30:00Z", "1", h1, "1");
        // 超过 2 位小数 -> 400
        putCurve(windowId, 400, h0, "1.001", h1, "1");
        // 负数 -> 400
        putCurve(windowId, 400, h0, "-1", h1, "1");
